		["Ah, very good. Now choose your addon: {first} or {second}."] = "Ah, muito bem. Agora escolha seu addon: {primeiro} ou {segundo}.",
		["Ah, you want to replace your adventurer's stone for 30 gold?"] = "Ah, você quer repor sua pedra do aventureiro por 30 de ouro?",
		["Ah, you want to replace your adventurer's stone for free?"] = "Ah, você quer repor sua pedra do aventureiro de graça?",
		["Al Dee has a general {equipment} store in the north-western part of the village. He sells useful stuff such as {ropes}."] = "Al Dee tem uma loja geral de {equipamento} na parte noroeste do vilarejo. Vende coisas úteis, como {cordas}.",
		["Alright then. Good luck on your travels."] = "Muito bem. Boa sorte nas suas viagens.",
		["Alright, come back if you have changed your mind."] = "Certo, volte se mudar de ideia.",
		["Alright, then just let me know when you're ready. Don't take too much time though."] = "Certo, então me avise quando estiver pronto. Mas não demore muito.",
		["Alright."] = "Certo.",
		["Alright. Can I help you with something else then?"] = "Certo. Posso ajudar com mais alguma coisa, então?",
		["Also buying minotaur leather."] = "Também compro couro de minotauro.",
		["Amber is such a lovely girl, and also a very experienced {explorer} and {adventurer}. It's always interesting to chat with her."] = "Amber é uma moça adorável, e também uma {exploradora} e {aventureiro} muito experiente. É sempre interessante conversar com ela.",
		["Are you crazy?!"] = "Você é louco?!",
		["Are you hungry? I'm sorry, I have no food here."] = "Está com fome? Sinto muito, não tenho comida aqui.",
		["Are you looking for the best trades? Come to my shop!"] = "Procura os melhores negócios? Venha à minha loja!",
		["Are you prepared for your next mission, |PLAYERNAME|?"] = "Está preparado para a próxima missão, |PLAYERNAME|?",
		["Are you trying to mess with me?!"] = "Está tentando me enrolar?!",
		["As a premium adventurer you have many advantages, you should check them out!"] = "Como aventureiro premium você tem muitas vantagens, vale conferir!",
		["As a premium adventurer you have many advantages. You really should check them out!"] = "Como aventureiro premium você tem muitas vantagens. Vale mesmo a pena conferir!",
		["As a premium adventurer, you are an official tax payer and thus privileged in many ways. For example, you can travel by {ship} and get better deals from {merchants}."] = "Como aventureiro premium, você é contribuinte oficial e por isso tem privilégios. Por exemplo, pode viajar de {navio} e conseguir preços melhores com os {comerciantes}.",
		["As an adventurer you should always have at least a {backpack}, a {rope}, a {shovel}, a {weapon}, an {armor} and a {shield}."] = "Como aventureiro, você deve ter sempre pelo menos uma {mochila}, uma {corda}, uma {pá}, uma {arma}, uma {armadura} e um {escudo}.",
		["As you wish."] = "Como quiser.",
		["At least you know how to address a man of my importance."] = "Ao menos você sabe se dirigir a um homem da minha importância.",
		["Aw, I guess you don't like feather hats. No big deal."] = "Ah, acho que você não gosta de chapéu de pena. Tudo bem.",
		["Be careful down there! Make sure you bought enough {torches} and a {rope} or you might get lost."] = "Cuidado lá embaixo! Garanta que comprou {tochas} suficientes e uma {corda}, ou pode acabar perdido.",
		["Be greeted, |PLAYERNAME|! As a tailor and merchant I have to say - we need to do something about your {outfit}, shall we?"] = "Saudações, |PLAYERNAME|! Como alfaiate e comerciante, preciso dizer: temos que fazer algo pelo seu {visual}, não é?",
		["Bespoke armor for all vocations! For the cost of some tokens only!"] = "Armadura sob medida para todas as vocações! Só por alguns tokens!",
		["Best place in town! Come to my bar!"] = "O melhor lugar da cidade! Venha ao meu bar!",
		["Billy is {Willie}'s cousin, but he has his farm on the {premium} side of the village."] = "Billy é primo do {Willie}, mas tem a fazenda no lado {premium} do vilarejo.",
		["Billy."] = "Billy.",
		["Blessings on your hunts!"] = "Bênçãos sobre suas caçadas!",
		["Blueberries grow on bushes. They're quite common in Tibia. Just pick them from a bush if you need a snack!"] = "Amoras crescem em arbustos, bem comuns em Tibia. É só colher de um arbusto se quiser um lanche!",
		["Boring little girl."] = "Menininha sem graça.",
		["Bread, cheese, ham and meat! All fresh!"] = "Pão, queijo, presunto e carne! Tudo fresco!",
		["Brilliant! We need fine adventurers like you! If you are ready to learn, just ask me for a lesson. You can always ask for the differently coloured words - such as this one - to continue the lesson."] = "Excelente! Precisamos de bons aventureiros como você! Quando estiver pronto para aprender, é só me pedir uma aula. Você sempre pode perguntar sobre as palavras de outra cor — como esta — para continuar a aula.",
		["Bugs plague this isle, but my wares are bug-free, totally bug-free."] = "Insetos infestam esta ilha, mas minhas mercadorias são livres de bicho, totalmente livres.",
		["Buy your weapons here!"] = "Compre suas armas aqui!",
		["Buying and selling food!"] = "Compro e vendo comida!",
		["Buying fresh corpses of rats, rabbits and wolves."] = "Compro carcaças frescas de ratos, coelhos e lobos.",
		["Buying fresh dead rats!"] = "Compro ratos mortos frescos!",
		["Buying many types of food and ingredients, too!"] = "Também compro vários tipos de comida e ingredientes!",
		["Bye, bye."] = "Tchau, tchau.",
		["Bye, |PLAYERNAME|."] = "Tchau, |PLAYERNAME|.",
		["Bye."] = "Tchau.",
		["CHILD! COME BACK WHEN YOU HAVE GROWN UP!"] = "CRIANÇA! VOLTE QUANDO TIVER CRESCIDO!",
		["COME BACK WHEN YOU ARE PREPARED TO FACE YOUR DESTINY!"] = "VOLTE QUANDO ESTIVER PREPARADO PARA ENCARAR SEU DESTINO!",
		["Can't stand him."] = "Não o suporto.",
		["Come back when you have killed enough minotaurs."] = "Volte quando tiver matado minotauros suficientes.",
		["Come over here if you have to resupply!"] = "Venha aqui se precisar se reabastecer!",
		["Come to me if you need healing!"] = "Venha até mim se precisar de cura!",
		["Death comes to the best of us, but this time you had no chance."] = "A morte chega aos melhores de nós, mas desta vez você não teve chance.",
		["Decent guy."] = "Sujeito decente.",
		["Did I hear my name somewhere?"] = "Ouvi meu nome por aí?",
		["Dixi sells and buys {armors}, {shields}, {helmets} and {legs}. You can find her shop south of the academy, just go up the stairs in {Obi}'s shop."] = "Dixi compra e vende {armaduras}, {escudos}, {elmos} e {perneiras}. A loja dela fica ao sul da academia; é só subir a escada na loja do {Obi}.",
		["Do I look like a clock?"] = "Eu tenho cara de relógio?",
		["Do I look like a tourist information centre? Go ask someone else."] = "Tenho cara de posto de informação turística? Pergunte a outra pessoa.",
		["Do you have a suitable present box for me?"] = "Você tem uma caixa de presente adequada para mim?",
		["Do you seek a passage to"] = "Você procura passagem para",
		["Do you want to appropriately show off your boss trophies and buy an additional podium of vigour for 1000000 Gold?"] = "Quer exibir seus troféus de boss como merecem e comprar mais um podium of vigour por 1000000 de ouro?",
		["Do you want to buy the dungeon key for 2000 gold?"] = "Quer comprar a chave da masmorra por 2000 de ouro?",
		["Do you want to buy |ITEMCOUNT| |ITEMNAME| for |TOTALCOST| gold coins?"] = "Quer comprar |ITEMCOUNT| |ITEMNAME| por |TOTALCOST| moedas de ouro?",
		["Don't despair! Help is near!"] = "Não se desespere! A ajuda está perto!",
		["Don't enter this area if you are an inexperienced fighter! It would be your end!"] = "Não entre nesta área se for um lutador inexperiente! Seria o seu fim!",
		["Don't forget to deposit your money here in the Global Bank before you head out for adventure."] = "Não esqueça de depositar seu dinheiro aqui no Global Bank antes de sair para a aventura.",
		["Don't forget to deposit your money here in the Tibian Bank before you head out for adventure."] = "Não esqueça de depositar seu dinheiro aqui no Tibian Bank antes de sair para a aventura.",
		["Don't forget to protect yourself with a shield!"] = "Não esqueça de se proteger com um escudo!",
		["Don't go hunting without proper equipment. You need at least a suitable {weapon}, {armor}, {shield}, {rope} and {shovel}. A {torch} is also good as well as {legs}, a {helmet} and {shoes}."] = "Não saia para caçar sem equipamento adequado. Você precisa no mínimo de uma {arma} decente, {armadura}, {escudo}, {corda} e {pá}. Uma {tocha} também ajuda, assim como {perneiras}, um {elmo} e {botas}.",
