		["For level 70 I have {Strong Flame Strike} for 6000 gold and {Strong Terra Strike} for 6000 gold."] = "No nível 70 eu tenho {Strong Flame Strike} por 6000 de ouro e {Strong Terra Strike} por 6000 de ouro.",
		["For level 70 I have {Strong Flame Strike} for 6000 gold."] = "No nível 70 eu tenho {Strong Flame Strike} por 6000 de ouro.",
