		["Would you really like to deposit"] = "Você realmente quer depositar",
		["YOU ALREADY HAVE A VOCATION!"] = "VOCÊ JÁ TEM UMA VOCAÇÃO!",
		["Ya take a good look."] = "Dê uma boa olhada.",
		["Yeah go away!"] = "É, some daqui!",
		["Yeah, bye |PLAYERNAME|."] = "É, tchau, |PLAYERNAME|.",
		["Yeah, so?"] = "É, e daí?",
		["Yes, I can sell that to you. Just ask me for a {trade} to see what I buy from you."] = "Sim, posso te vender isso. Peça para {negociar} e veja o que compro de você.",
		["Yes, I sell small health potions. Ask me for a trade if you need one."] = "Sim, vendo small health potions. Peça para negociar se precisar de uma.",
		["Yes, I'm selling weapons. Just ask me for a {trade} to see my offers and the things I buy from you."] = "Sim, vendo armas. Peça para {negociar} e veja minhas ofertas e o que compro de você.",
		["Yes, Paulie is very important. He is the local {bank} clerk."] = "Sim, Paulie é muito importante. É o funcionário do {banco} daqui.",
		["Yes, depositing your money will keep it safe, so it is a good idea to store it in the bank. Of course, you can always withdraw it again."] = "Sim, depositar mantém seu dinheiro seguro, então é boa ideia guardá-lo no banco. E claro, você pode sacar quando quiser.",
		["Yes? How can I {help} you?"] = "Sim? Como posso te {ajuda}?",
		["Yes? What may I do for you, |PLAYERNAME|? Bank business, perhaps?"] = "Sim? O que posso fazer por você, |PLAYERNAME|? Assunto de banco, talvez?",
		["You are at Fibula. This isle is not very dangerous. Just the wolves bother outside the village."] = "Você está em Fibula. Esta ilha não é muito perigosa. Só os lobos incomodam fora do vilarejo.",
		["You are hurt, my child. I will heal your wounds."] = "Você está ferido, meu filho. Vou curar suas feridas.",
		["You are poisoned. I will help you."] = "Você está envenenado. Vou te ajudar.",
		["You are pretty inexperienced. I think killing rats is a suitable challenge for you. For each fresh {dead rat} I will give you two shiny coins of gold."] = "Você é bastante inexperiente. Acho que caçar ratos é um desafio à sua altura. Por cada {rato morto} fresco eu te dou duas moedas de ouro reluzentes.",
		["You aren't looking really bad, |PLAYERNAME|. I can only help in cases of real emergencies. Raise your health simply by eating {food}."] = "Você não está tão mal assim, |PLAYERNAME|. Só posso ajudar em emergências de verdade. Recupere sua vida comendo {comida}.",
		["You aren't looking that bad. Sorry, I can't help you. But if you are looking for additional protection you should go on the {pilgrimage} of ashes or get the protection of the {twist of fate} here."] = "Você não está tão mal assim. Desculpe, não posso ajudar. Mas se procura proteção adicional, faça a {peregrinação} das cinzas ou receba a proteção da {reviravolta do destino} aqui.",
		["You can ask for the blessing of spiritual shielding in the whiteflower temple south of Thais."] = "Você pode pedir a bênção do escudo espiritual no templo da flor branca ao sul de Thais.",
		["You can ask for the blessing of the two suns in the suntower near Ab'Dendriel."] = "Você pode pedir a bênção dos dois sóis na torre do sol perto de Ab'Dendriel.",
		["You can buy and sell goods from merchants. To do so, simply talk to them and ask them for a {trade}. They will gladly show you their offers and also the things they buy from you."] = "Você pode comprar e vender com os comerciantes. Basta falar com eles e pedir para {negociar}. Eles mostram com prazer as ofertas e também o que compram de você.",
		["You can buy equipment from the {merchants} in this village once you earned some {gold}. Some {monsters} also carry equipment pieces with them."] = "Você pode comprar equipamento com os {comerciantes} do vilarejo assim que juntar algum {ouro}. Alguns {monstros} também carregam peças de equipamento.",
		["You can deposit your money at the bank. That way you won't lose it if you get {killed}. The bank is just under the academy and to the right."] = "Você pode depositar seu dinheiro no banco. Assim não o perde se {morrer}. O banco fica logo abaixo da academia, à direita.",
		["You can deposit your {money} there to keep it safe. However, you still need cash to buy something here."] = "Você pode depositar seu {dinheiro} lá para ficar seguro. Mas ainda vai precisar de trocado para comprar aqui.",
		["You can earn a fair amount of gold by fighting {monsters} and picking up the things they carry. Many {citizens} are buying some of that loot, simply ask around."] = "Dá para juntar bastante ouro combatendo {monstros} e recolhendo o que eles carregam. Muitos {moradores} compram esse loot; é só perguntar por aí.",
		["You can even sell some corpses! For example, you can sell fresh dead rats to {Tom} the tanner or me. He also buys other dead creatures, just ask him for a {trade}."] = "Dá até para vender algumas carcaças! Por exemplo, ratos mortos frescos você vende ao {Tom}, o curtidor, ou a mim. Ele também compra outras criaturas mortas; é só pedir para {negociar}.",
		["You can find the oracle on the top floor of the {academy}, just above {Seymour}. Go there when you are level 8 to find your {destiny}."] = "O oráculo fica no último andar da {academia}, logo acima do {Seymour}. Vá até lá ao chegar ao nível 8 para descobrir seu {destino}.",
		["You can leave for mainland once you are level 8. To do so talk to the {oracle}."] = "Você pode partir para o continente ao chegar ao nível 8. Para isso, fale com o {oráculo}.",
		["You definitely need a rope to progress in dungeons, else you might end up stuck. Buy one from {Al Dee} or {Lee'Delle}."] = "Você precisa mesmo de uma corda para avançar nas masmorras, senão acaba preso lá embaixo. Compre uma com {Al Dee} ou {Lee'Delle}.",
		["You do not have enough capacity for all items."] = "Você não tem capacidade para todos os itens.",
		["You do not have enough gold."] = "Você não tem ouro suficiente.",
		["You do not have enough money to donate that amount."] = "Você não tem dinheiro suficiente para doar essa quantia.",
		["You do not have this object."] = "Você não tem esse objeto.",
		["You don't have enough capacity. You must have"] = "Você não tem capacidade. Precisa ter",
		["You don't have enough money."] = "Você não tem dinheiro suficiente.",
		["You don't have it..."] = "Você não tem isso...",
		["You don't have so many."] = "Você não tem tantos assim.",
		["You gain experience when fighting {monsters}. You can take a look at your skill window to check your progress."] = "Você ganha experiência combatendo {monstros}. Dê uma olhada na janela de skills para acompanhar seu progresso.",
		["You have a present for me?? Realy?"] = "Tem um presente para mim?? Sério?",
		["You have already started that mission."] = "Você já começou essa missão.",
		["You have done well. Here, take your reward."] = "Você se saiu bem. Tome, aqui está sua recompensa.",
		["You have not aquired enough knowledge in hunting big scary creatures."] = "Você ainda não acumulou conhecimento suficiente caçando criaturas grandes e assustadoras.",
		["You have not started that mission."] = "Você não começou essa missão.",
		["You have to fight {monsters} to train your {skills} and {level}. If you lose {health}, eat {food} to regain it or use a {potion}."] = "Você precisa combater {monstros} para treinar suas {skills} e seu {nível}. Se perder {vida}, coma {comida} para recuperar ou use uma {potion}.",
		["You just swapped 20 silver raid tokens for 1"] = "Você acabou de trocar 20 silver raid tokens por 1",
		["You know you want a party after all that tiring hunting!"] = "Você sabe que quer uma festa depois de tanta caçada cansativa!",
		["You managed to deceive Erayo? Impressive. Well, I guess, since you have come that far, I might as well give you a task too, eh?"] = "Você conseguiu enganar o Erayo? Impressionante. Bom, já que chegou até aqui, acho que também posso te dar uma tarefa, hein?",
		["You must have passed the house of Lily on your way here. She sells {potions}. If you pick blueberries or find cookies, she'll buy them from you."] = "Você deve ter passado pela casa da Lily no caminho até aqui. Ela vende {potions}. Se colher amoras ou achar biscoitos, ela compra de você.",
		["You need at least a {backpack}, a {rope}, a {shovel}, a {weapon}, an {armor} and a {shield}."] = "Você precisa no mínimo de uma {mochila}, uma {corda}, uma {pá}, uma {arma}, uma {armadura} e um {escudo}.",
		["You see, I'm quite hungry from standing here all day. Could you get me some {food}?"] = "Sabe, fico faminto de tanto ficar aqui o dia todo. Pode me arrumar alguma {comida}?",
		["You should not descend into dungeons without proper {equipment}. Once you are all prepared, ask the bridge {guards} for suitable {monsters}."] = "Não desça às masmorras sem {equipamento} adequado. Quando estiver preparado, pergunte aos {guardas} das pontes sobre {monstros} à sua altura.",
		["You shouldn't miss the experience."] = "Você não devia perder essa experiência.",
		["You still need to kill"] = "Você ainda precisa matar",
		["You want me to transport you and your spouse to Honeymoon Island {Meluna}?"] = "Quer que eu leve você e seu cônjuge à Honeymoon Island {meluna}?",
		["You, over there! Stop sniffing around my farm! Either trade with me or leave!"] = "Ei, você aí! Pare de bisbilhotar minha fazenda! Ou negocia comigo, ou vai embora!",
		["Your current health is shown by the red bar on the right side. {Death} awaits you if it goes down to zero."] = "Sua vida atual aparece na barra vermelha do lado direito. A {morte} te espera se ela chegar a zero.",
		["Your decision. Come back if you have changed your mind."] = "A decisão é sua. Volte se mudar de ideia.",
		["Your near destiny will be to choose a {vocation} once you are level 8. Whether you will become a {knight}, {sorcerer}, {paladin} or {druid} is a big decision!"] = "Seu destino próximo é escolher uma {vocação} ao chegar ao nível 8. Se você será {knight}, {sorcerer}, {paladin} ou {druid} é uma grande decisão!",
		["{Al Dee} sells torches."] = "{Al Dee} vende tochas.",
		["{Dixi} and {Lee'Delle} sell my leather clothes in their shops."] = "{Dixi} e {Lee'Delle} vendem minhas roupas de couro nas lojas delas.",
		["{KNIGHT}, {PALADIN}, {SORCERER}, {DRUID}, OR {MONK}?"] = "{KNIGHT}, {PALADIN}, {SORCERER}, {DRUID} OU {MONK}?",
		["|PLAYERNAME|, I am already talking to you."] = "|PLAYERNAME|, já estou falando com você.",
	},

	-- Mesma traducao indexada por chave tolerante (minuscula, espaco
	-- colapsado, pontuacao de borda fora). E o que impede a traducao de
	-- se perder calada quando o upstream mexe numa virgula.
	tolerantes = {
		["sigh> the world has grown complicated since my youth"] = "<suspira> O mundo ficou complicado desde a minha juventude.",
		["a druid! are you sure? this decision is irreversible"] = "UM DRUID! TEM CERTEZA? ESTA DECISÃO É IRREVERSÍVEL!",
		["a knight! are you sure? this decision is irreversible"] = "UM KNIGHT! TEM CERTEZA? ESTA DECISÃO É IRREVERSÍVEL!",
		["a monk! are you sure? this decision is irreversible"] = "UM MONK! TEM CERTEZA? ESTA DECISÃO É IRREVERSÍVEL!",
		["a paladin! are you sure? this decision is irreversible"] = "UM PALADIN! TEM CERTEZA? ESTA DECISÃO É IRREVERSÍVEL!",
		["a sorcerer! are you sure? this decision is irreversible"] = "UM SORCERER! TEM CERTEZA? ESTA DECISÃO É IRREVERSÍVEL!",
		["a fine and helpful man. without him, many new adventurers would be quite clueless"] = "Um homem bom e prestativo. Sem ele, muitos aventureiros novos ficariam completamente perdidos.",
		["a humble monk living in the {temple} south of here. he can heal you if you are wounded or poisoned"] = "Um humilde monge que vive no {templo} ao sul daqui. Ele te cura se você estiver ferido ou envenenado.",
		["a mysterious druid who lives somewhere in the wilderness. he sells small health {potions} just like {lily}"] = "Um druida misterioso que vive em algum lugar do ermo. Ele vende small health {potions}, assim como a {Lily}.",
		["a place to learn about {tibia}"] = "Um lugar para aprender sobre {Tibia}.",
		["a shovel is needed to dig some {dungeon} entrances open. 'use' it on a loose stone pile to make a hole large enough to enter"] = "A pá serve para abrir algumas entradas de {masmorra}. Use-a num monte de pedras soltas para fazer um buraco grande o bastante.",
		["a single rat doesn't pose a grave danger to you, but be careful not to get cornered by many of them. they could still {kill} you"] = "Um rato sozinho não é grande perigo, mas cuidado para não ser encurralado por vários. Juntos eles ainda podem te {matar}.",
		["a sturdy leather helmet is a good choice for a beginner. you can either buy it from {dixi} and {lee'delle}, or, once you are strong enough, {loot} them from {trolls}"] = "Um leather helmet resistente é boa escolha para iniciante. Dá para comprar com {Dixi} e {Lee'Delle} ou, quando estiver forte o bastante, tirar no {loot} dos {trolls}.",
		["a torch will provide you with light in dark {dungeons}. 'use' it to light it. you can buy them from {al dee} or {lee'delle}"] = "A tocha te dá luz nas {masmorras} escuras. Use-a para acendê-la. Dá para comprar com {Al Dee} ou {Lee'Delle}.",
		["a traveller from the {main} continent. i wonder what brought her here. no one comes here of his own free will"] = "Uma viajante do {continente}. Fico imaginando o que a trouxe até aqui. Ninguém vem para cá por vontade própria.",
		["about time we got a bar here"] = "Já era hora de termos um bar aqui.",
		["actually i think you have killed enough. you should reply with {yes}"] = "Na verdade acho que você já matou o bastante. Devia responder {sim}!",
		["ah, i see you killed a lot of dangerous creatures. here's your podium of vigour"] = "Ah, vejo que você matou muitas criaturas perigosas. Aqui está seu podium of vigour!",
		["ah, another adventurer. let's talk a little"] = "Ah, mais um aventureiro. Vamos conversar um pouco.",
		["ah, excellent. here is your"] = "Ah, excelente. Aqui está seu",
		["ah, the monsters are far away. let's party now"] = "Ah, os monstros estão longe. Vamos festejar!",
		["ah, very good. now choose your addon: {first} or {second}"] = "Ah, muito bem. Agora escolha seu addon: {primeiro} ou {segundo}.",
		["ah, you want to replace your adventurer's stone for 30 gold"] = "Ah, você quer repor sua pedra do aventureiro por 30 de ouro?",
		["ah, you want to replace your adventurer's stone for free"] = "Ah, você quer repor sua pedra do aventureiro de graça?",
		["al dee has a general {equipment} store in the north-western part of the village. he sells useful stuff such as {ropes}"] = "Al Dee tem uma loja geral de {equipamento} na parte noroeste do vilarejo. Vende coisas úteis, como {cordas}.",
		["alright then. good luck on your travels"] = "Muito bem. Boa sorte nas suas viagens.",
		["alright, come back if you have changed your mind"] = "Certo, volte se mudar de ideia.",
		["alright, then just let me know when you're ready. don't take too much time though"] = "Certo, então me avise quando estiver pronto. Mas não demore muito.",
		["alright"] = "Certo.",
		["alright. can i help you with something else then"] = "Certo. Posso ajudar com mais alguma coisa, então?",
		["also buying minotaur leather"] = "Também compro couro de minotauro.",
		["amber is such a lovely girl, and also a very experienced {explorer} and {adventurer}. it's always interesting to chat with her"] = "Amber é uma moça adorável, e também uma {exploradora} e {aventureiro} muito experiente. É sempre interessante conversar com ela.",
		["are you crazy"] = "Você é louco?!",
		["are you hungry? i'm sorry, i have no food here"] = "Está com fome? Sinto muito, não tenho comida aqui.",
		["are you looking for the best trades? come to my shop"] = "Procura os melhores negócios? Venha à minha loja!",
		["are you prepared for your next mission, |playername|"] = "Está preparado para a próxima missão, |PLAYERNAME|?",
		["are you trying to mess with me"] = "Está tentando me enrolar?!",
		["as a premium adventurer you have many advantages, you should check them out"] = "Como aventureiro premium você tem muitas vantagens, vale conferir!",
		["as a premium adventurer you have many advantages. you really should check them out"] = "Como aventureiro premium você tem muitas vantagens. Vale mesmo a pena conferir!",
		["as a premium adventurer, you are an official tax payer and thus privileged in many ways. for example, you can travel by {ship} and get better deals from {merchants}"] = "Como aventureiro premium, você é contribuinte oficial e por isso tem privilégios. Por exemplo, pode viajar de {navio} e conseguir preços melhores com os {comerciantes}.",
		["as an adventurer you should always have at least a {backpack}, a {rope}, a {shovel}, a {weapon}, an {armor} and a {shield}"] = "Como aventureiro, você deve ter sempre pelo menos uma {mochila}, uma {corda}, uma {pá}, uma {arma}, uma {armadura} e um {escudo}.",
		["as you wish"] = "Como quiser.",
		["at least you know how to address a man of my importance"] = "Ao menos você sabe se dirigir a um homem da minha importância.",
		["aw, i guess you don't like feather hats. no big deal"] = "Ah, acho que você não gosta de chapéu de pena. Tudo bem.",
		["be careful down there! make sure you bought enough {torches} and a {rope} or you might get lost"] = "Cuidado lá embaixo! Garanta que comprou {tochas} suficientes e uma {corda}, ou pode acabar perdido.",
		["be greeted, |playername|! as a tailor and merchant i have to say - we need to do something about your {outfit}, shall we"] = "Saudações, |PLAYERNAME|! Como alfaiate e comerciante, preciso dizer: temos que fazer algo pelo seu {visual}, não é?",
		["bespoke armor for all vocations! for the cost of some tokens only"] = "Armadura sob medida para todas as vocações! Só por alguns tokens!",
		["best place in town! come to my bar"] = "O melhor lugar da cidade! Venha ao meu bar!",
		["billy is {willie}'s cousin, but he has his farm on the {premium} side of the village"] = "Billy é primo do {Willie}, mas tem a fazenda no lado {premium} do vilarejo.",
		["billy"] = "Billy.",
		["blessings on your hunts"] = "Bênçãos sobre suas caçadas!",
		["blueberries grow on bushes. they're quite common in tibia. just pick them from a bush if you need a snack"] = "Amoras crescem em arbustos, bem comuns em Tibia. É só colher de um arbusto se quiser um lanche!",
		["boring little girl"] = "Menininha sem graça.",
		["bread, cheese, ham and meat! all fresh"] = "Pão, queijo, presunto e carne! Tudo fresco!",
		["brilliant! we need fine adventurers like you! if you are ready to learn, just ask me for a lesson. you can always ask for the differently coloured words - such as this one - to continue the lesson"] = "Excelente! Precisamos de bons aventureiros como você! Quando estiver pronto para aprender, é só me pedir uma aula. Você sempre pode perguntar sobre as palavras de outra cor — como esta — para continuar a aula.",
		["bugs plague this isle, but my wares are bug-free, totally bug-free"] = "Insetos infestam esta ilha, mas minhas mercadorias são livres de bicho, totalmente livres.",
		["buy your weapons here"] = "Compre suas armas aqui!",
		["buying and selling food"] = "Compro e vendo comida!",
		["buying fresh corpses of rats, rabbits and wolves"] = "Compro carcaças frescas de ratos, coelhos e lobos.",
		["buying fresh dead rats"] = "Compro ratos mortos frescos!",
		["buying many types of food and ingredients, too"] = "Também compro vários tipos de comida e ingredientes!",
		["bye, bye"] = "Tchau, tchau.",
		["bye, |playername|"] = "Tchau, |PLAYERNAME|.",
		["bye"] = "Tchau.",
		["child! come back when you have grown up"] = "CRIANÇA! VOLTE QUANDO TIVER CRESCIDO!",
		["come back when you are prepared to face your destiny"] = "VOLTE QUANDO ESTIVER PREPARADO PARA ENCARAR SEU DESTINO!",
		["can't stand him"] = "Não o suporto.",
		["come back when you have killed enough minotaurs"] = "Volte quando tiver matado minotauros suficientes.",
		["come over here if you have to resupply"] = "Venha aqui se precisar se reabastecer!",
		["come to me if you need healing"] = "Venha até mim se precisar de cura!",
		["death comes to the best of us, but this time you had no chance"] = "A morte chega aos melhores de nós, mas desta vez você não teve chance.",
		["decent guy"] = "Sujeito decente.",
		["did i hear my name somewhere"] = "Ouvi meu nome por aí?",
		["dixi sells and buys {armors}, {shields}, {helmets} and {legs}. you can find her shop south of the academy, just go up the stairs in {obi}'s shop"] = "Dixi compra e vende {armaduras}, {escudos}, {elmos} e {perneiras}. A loja dela fica ao sul da academia; é só subir a escada na loja do {Obi}.",
		["do i look like a clock"] = "Eu tenho cara de relógio?",
